        from scipy.integrate import solve_ivp
        C = lambda t: pk_conc(dose, t)
        kin = p['R0']*p['kout']
        def f(t, R):
            c = C(t)
            inh = p['Imax']*c**p['kin_hill']/(p['IC50']**p['kin_hill']+c**p['kin_hill'])
            return [kin*(1-inh) - p['kout']*R[0]]
